Implementation of an S-Class R-Tree spatial index for 2D bounding boxes,
supporting dynamic insertions, spatial range queries, and nearest-neighbor search.
"""

import math
from typing import Any, List, Optional, Tuple

# Type definitions
BoundingBox = Tuple[float, float, float, float]  # (min_x, min_y, max_x, max_y)


def _bbox_union(b1: BoundingBox, b2: BoundingBox) -> BoundingBox:
    """Computes the minimum bounding box enclosing b1 and b2."""
    return (
        min(b1[0], b2[0]),
        min(b1[1], b2[1]),
        max(b1[2], b2[2]),
        max(b1[3], b2[3]),
    )


def _bbox_area(b: BoundingBox) -> float:
    """Computes the surface area (2D area) of a bounding box."""
    width = max(0.0, b[2] - b[0])
    height = max(0.0, b[3] - b[1])
    return width * height


def _enlargement(b1: BoundingBox, b2: BoundingBox) -> float:
    """Computes the area increase required for b1 to include b2."""
    u = _bbox_union(b1, b2)
    return _bbox_area(u) - _bbox_area(b1)


def _intersects(b1: BoundingBox, b2: BoundingBox) -> bool:
    """Checks if two 2D bounding boxes intersect."""
    return not (b1[2] < b2[0] or b1[0] > b2[2] or b1[3] < b2[1] or b1[1] > b2[3])


def _min_dist_to_bbox(point: Tuple[float, float], b: BoundingBox) -> float:
    """Computes the minimum squared Euclidean distance from a point to a bounding box."""
    px, py = point
    dx = 0.0
    if px < b[0]:
        dx = b[0] - px
    elif px > b[2]:
        dx = px - b[2]

    dy = 0.0
    if py < b[1]:
        dy = b[1] - py
    elif py > b[3]:
        dy = py - b[3]

    return dx * dx + dy * dy


class RTreeNode:
    """Node in the R-Tree (can be internal or leaf)."""

    def __init__(self, is_leaf: bool = False):
        self.is_leaf = is_leaf
        self.entries: List[Tuple[BoundingBox, Any]] = (
            []
        )  # Leaf: (bbox, item_id), Internal: (bbox, RTreeNode)
        self.parent: Optional["RTreeNode"] = None

    @property
    def bbox(self) -> BoundingBox:
        if not self.entries:
            return (0.0, 0.0, 0.0, 0.0)
        b = self.entries[0][0]
        for entry in self.entries[1:]:
            b = _bbox_union(b, entry[0])
        return b


class RTreeSpatialIndex:
    """An R-Tree spatial index for 2D bounding boxes."""

    def __init__(self, max_entries: int = 4, min_entries: int = 2):
        self.max_entries = max(4, max_entries)
        self.min_entries = max(2, min(min_entries, self.max_entries // 2))
        self.root = RTreeNode(is_leaf=True)

    def insert(self, item_id: Any, bbox: BoundingBox) -> None:
        """Inserts an item with an associated 2D bounding box into the index."""
        leaf = self._choose_leaf(self.root, bbox)
        leaf.entries.append((bbox, item_id))

        if len(leaf.entries) > self.max_entries:
            self._handle_overflow(leaf)

    def search(self, query_bbox: BoundingBox) -> List[Any]:
        """Performs a spatial range query returning item IDs intersecting query_bbox."""
        results: List[Any] = []
        self._range_search(self.root, query_bbox, results)
        return results

    def nearest_neighbor(
        self, point: Tuple[float, float], k: int = 1
